	public LandingGear getLandingGear( LandingGearFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "LandingGearFetchOneSummary arg cannot be null" );

		LandingGear entity = null;
		UUID id = summary.getLandingGearId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a LandingGear using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


